             data,
             function (key, val) {
                 if (this[key] instanceof Buffer) {
                     return '<Buffer>';
                 }
                 if (this[key] instanceof Function) {
                     return '<Function>';
                 }
                 if (_.isPlainObject(this[key]) && !_.size(this[key])) {
                     return '{}';
                 }
                 return val;
