             });
     }

     function buildDefault(filePath, stat) {
         const p = Path.parse(filePath);
         p.path = filePath;
         p.stat = stat;
         return p;
     }

     return objectify(root);
 }

 function checkIsBinary(file) {
     try {
         return Promise.resolve(isBinary(file.path, null));
     } catch (err) {
         return Promise.reject(err);
     }
